from pathlib import Path
import json
D=Path(__file__).resolve().parent;R=D.parents[1];changes=json.loads((D/'changes.json').read_text())
def edit(name,old,new):
 p=R/name;s=p.read_text();assert s.count(old)==1;(D/'last-refinement-precheck.txt').write_text('Checked unchanged scientific counts; exact/primary distinction retained; one evidence/discovery spine. Local compression only.\n');p.write_text(s.replace(old,new));changes.append(dict(file=name,old=old,new=new))
